<script>
  let { room, session, host, busy, connected, phases, canStart, copied, meId, onCommand, onCopy } = $props();
</script>

<main class="main"><div class="page-heading"><div><p class="eyebrow">{room.title} · SESSION {session.id.slice(0,6).toUpperCase()}</p><h1 class="heading-one page-title">{phases[session.phase]}</h1></div><span class="tag">시나리오 v{session.scenarioVersion}</span></div><nav class="steps" aria-label="게임 진행 단계">{#each Object.entries(phases) as [key,label],i}<span class:active={session.phase===key} class="step">{String(i+1).padStart(2,'0')} {label}</span>{/each}</nav><div class="lobby-grid"><section class="panel story"><p class="eyebrow">{session.phase==='briefing'?'YOUR SECRET':'THE EVIDENCE'}</p>{#if session.phase==='briefing'}<h2 class="heading-two">너의 역할은 ‘{session.role.name}’</h2><p class="narrative">{session.role.secret}</p><p class="fine">이 정보는 너에게만 보여. 어떻게 이야기할지는 네가 결정해.</p>{:else if session.phase==='discussion'}<h2 class="heading-two">증언을 맞춰 볼 시간</h2>{#each session.clues as clue,i}<div class="clue"><span class="clue-label">단서 {i+1}</span><p class="clue-text">{clue}</p></div>{/each}<p class="fine">대화는 대면 또는 디스코드를 이용해 줘.</p>{:else if session.phase==='voting'}<h2 class="heading-two">누가 초대장을 옮겼을까?</h2><p class="muted">투표는 한 번만 가능하고, 모두 완료하면 진상이 공개돼.</p><div class="votes">{#each room.members as member}<button class="secondary" disabled={busy||!connected||session.hasVoted} onclick={()=>onCommand('vote',member.id)}>{member.nickname} 지목하기 →</button>{/each}</div><p class="fine">{session.hasVoted?'투표 완료. 다른 참가자들을 기다리고 있어.':'증언과 단서를 생각하고 한 명을 골라 줘.'} ({session.voteCount}/{room.count})</p>{:else}<h2 class="heading-two">사라진 초대장의 행방</h2><p class="narrative">{session.result?.answer}</p>{#each session.result?.votes??[] as vote}<p class="vote-result">{vote.voter} <span class="vote-target">→</span> {vote.target}</p>{/each}{/if}</section><aside class="sidebar"><section class="panel"><p class="eyebrow">PRIVATE ROLE CARD</p><details open={session.phase==='briefing'}><summary class="summary">{session.role.name} · 내 비밀 보기</summary><p class="muted detail-copy">{session.role.secret}</p></details></section><section class="panel"><h3 class="heading-three">다음 진행</h3>{#if host}{#if session.phase==='briefing'||session.phase==='discussion'}<p class="muted">모두 준비됐는지 대화로 확인하고 진행해 줘.</p><button class="primary" disabled={busy||!connected} onclick={()=>onCommand('advance')}>{session.phase==='briefing'?'단서 공개하기':'투표 시작하기'} →</button>{:else if session.phase==='reveal'}<button class="primary" disabled={busy||!connected} onclick={()=>onCommand('return')}>대기방으로 돌아가기 →</button>{:else}<p class="muted">모두 투표하면 결말이 공개돼.</p>{/if}{:else}<p class="muted">{session.phase==='voting'?'모두 투표하면 결말이 공개돼.':'방장이 다음 단계로 진행할 거야.'}</p>{/if}</section></aside></div></main>
